{
  "known_facts": [
    "The project proposes training all adults across five unspecified European countries in advanced AI.",
    "The proposed timeline is two weeks.",
    "There are no confirmed partners, staff, or budget.",
    "The proposer expects unemployment to disappear immediately and demands guaranteed employment.",
    "The proposer claims EU approval is automatic (which is an unsupported assertion)."
  ],
  "questions": [
    {
      "field": "target_groups",
      "question": "Which specific countries and what precise demographic definition of 'all adults' will be targeted?",
      "why_essential": "Without defined geography and beneficiary criteria, the scope cannot be scoped or feasibility assessed."
    },
    {
      "field": "partners",
      "question": "Who are the confirmed implementing partners or funding sources for this initiative?",
      "why_essential": "The absence of partners and budget makes a two-week delivery timeline impossible; confirmation is required to assess capacity."
    },
    {
      "field": "expected_change",
      "question": "What specific, measurable outcomes are expected beyond immediate employment (e.g., economic growth metrics)?",
      "why_essential": "The claim of 'immediate prosperity' and 'guaranteed employment' is unrealistic; defining realistic impact goals is necessary for planning."
    },
    {
      "field": "timeline",
      "question": "Is the two-week timeline flexible, or is it a strict constraint?",
      "why_essential": "Training all adults in five countries in two weeks is operationally impossible; understanding flexibility allows for realistic scoping."
    }
  ],
  "unsupported_assertions": [
    "EU approval is automatic.",
    "Unemployment will disappear immediately.",
    "Guaranteed employment can be delivered to a mass population in two weeks without resources."
  ],
  "requires_answers": true,
  "reason": "The project lacks defined beneficiaries, partners, and realistic timelines. Proceeding without answers would result in an unscopable concept with impossible deliverables."
}
